<?php
require_once __DIR__.'/lib/auth.php';requireAuth();$pdo=db();$user=currentUser();$ownerId=(int)$pdo->query('SELECT MIN(id) FROM users')->fetchColumn();if((int)$user['id']!==$ownerId){http_response_code(403);exit('Owner access required.');}
require_once __DIR__.'/lib/integrations.php';require_once __DIR__.'/lib/email_api_mailer.php';require_once __DIR__.'/lib/smtp_mailer.php';require_once __DIR__.'/lib/interview_confirmation.php';
$testing=integrationConfig('email_testing');$defaultEmail=(string)($testing['email']??$user['email']??'');$message='';$error='';
$stmt=$pdo->prepare("SELECT ii.id,ii.recipient_email,ib.timezone,c.name candidate_name,j.title job_title,s.starts_at,s.ends_at FROM interview_invitations ii JOIN interview_batches ib ON ib.id=ii.batch_id JOIN candidates c ON c.id=ii.candidate_id JOIN jobs j ON j.id=ib.job_id JOIN interview_slots s ON s.id=ii.confirmed_slot_id WHERE ii.status='confirmed' AND ib.created_by=? ORDER BY s.starts_at DESC LIMIT 1");$stmt->execute([$user['id']]);$invitation=$stmt->fetch();
if($_SERVER['REQUEST_METHOD']==='POST')try{if(!verifyCsrf($_POST['csrf']??''))throw new RuntimeException('Session expired.');$to=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);if(!$to)throw new RuntimeException('Enter a valid test email.');if(!$invitation)throw new RuntimeException('Confirm at least one interview before testing.');$html=interviewConfirmationHtml($invitation,$invitation);$subject='[CALENDAR TEST] Interview confirmed - '.$invitation['job_title'];$api=integrationConfig('email_api');if(($api['status']??'')==='configured'&&!empty($api['url']))emailApiSendHtml($api,[$to],$subject,$html);else{$smtp=integrationConfig('smtp');if(($smtp['status']??'')!=='configured')throw new RuntimeException('No email delivery integration is configured.');smtpSendHtml($smtp,$to,$subject,$html);}$pdo->prepare("INSERT INTO audit_events(user_id,action,entity_type,entity_id,metadata_json) VALUES(?,'interview.calendar_test_sent','interview_invitation',?,?)")->execute([$user['id'],(string)$invitation['id'],json_encode(['test_recipient'=>$to,'outcome'=>'success'])]);$message='Calendar test email sent only to '.$to.'.';}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Calendar mail test</title><style>body{font:14px Arial;background:#f5f5f8;padding:30px;color:#1d1b24}.card{max-width:620px;margin:auto;background:#fff;border:1px solid #e6e3ec;border-radius:12px;padding:28px}input,button{width:100%;box-sizing:border-box;padding:12px;margin-top:9px;border:1px solid #ddd7e9;border-radius:7px}button{background:#6843e9;color:#fff;font-weight:bold}.ok{color:#087a55}.error{color:#b4233c}.muted{color:#777}</style></head><body><main class="card"><h1>Interview calendar email test</h1><p class="muted">Uses the latest confirmed interview date/time, but sends only to the test address below.</p><?php if($invitation):?><p><strong><?=htmlspecialchars($invitation['candidate_name'])?></strong> · <?=htmlspecialchars($invitation['job_title'])?><br><?=htmlspecialchars($invitation['starts_at'])?> · <?=htmlspecialchars($invitation['timezone'])?></p><?php endif?><?php if($message):?><p class="ok"><?=htmlspecialchars($message)?></p><?php endif?><?php if($error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrfToken())?>"><label>Send test only to</label><input type="email" name="email" value="<?=htmlspecialchars($defaultEmail)?>" required><button type="submit">Send calendar test email</button></form><p class="muted">Delete this file from the server after testing.</p></main></body></html>
